import React, { useEffect, useState } from "react";
import axios from "axios";
import jsPDF from "jspdf";
import { API_URL } from "../config";

function BallotReceiptPage({ auth }) {
  const [votes, setVotes] = useState([]);
  const [loading, setLoading] = useState(true);

  // Feedback states
  const [feedback, setFeedback] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (!auth?.token) return;

    const fetchVotes = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/vote/my`, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });

        // ✅ FIXED: only check candidateId (remove candidateName)
        const userVotes = res.data.filter(v => v.candidateId);

        setVotes(userVotes);
      } catch (err) {
        console.error("Failed to fetch your votes:", err);
        alert("Failed to load your ballot.");
      } finally {
        setLoading(false);
      }
    };

    fetchVotes();
  }, [auth]);

  // =========================
  // SUBMIT FEEDBACK
  // =========================
  const handleSubmitFeedback = async () => {
    if (!feedback.trim()) {
      setMessage("Please enter feedback.");
      return;
    }

    try {
      setSubmitting(true);

      const res = await axios.post(
        `${API_URL}/api/feedback`,
        { message: feedback },
        {
          headers: { Authorization: `Bearer ${auth.token}` },
        }
      );

      setMessage(res.data.message || "Feedback submitted!");
      setFeedback("");
    } catch (err) {
      console.error(err);
      setMessage(err.response?.data?.message || "Failed to submit feedback.");
    } finally {
      setSubmitting(false);
    }
  };

  // =========================
  // DOWNLOAD PDF
  // =========================
  const downloadPDF = () => {
    const doc = new jsPDF();

    doc.setFontSize(16);
    doc.text("SorSU Voting Receipt", 20, 20);

    doc.setFontSize(12);
    doc.text(`Date: ${new Date().toLocaleString()}`, 20, 28);

    votes.forEach((v, i) => {
      const name = `${v.candidateId?.firstName} ${v.candidateId?.lastName}`;
      const position = v.candidateId?.candidacy;

      doc.text(`${i + 1}. ${position} - ${name}`, 20, 38 + i * 10);
    });

    doc.save("ballot-receipt.pdf");
  };

  if (loading) return <p>Loading your ballot...</p>;

  return (
    <div style={{ maxWidth: 700, margin: "40px auto", textAlign: "center" }}>
      <h2>🗳️ Your Ballot</h2>

      {votes.length === 0 ? (
        <p>You haven't voted yet.</p>
      ) : (
        <>
          {/* =========================
              VOTES LIST
          ========================= */}
          <div style={{ marginTop: 20, textAlign: "left" }}>
            {votes.map((v) => (
              <div
                key={v._id} // ✅ FIXED KEY
                style={{
                  padding: 15,
                  marginBottom: 10,
                  backgroundColor: "#fff",
                  borderRadius: 10,
                  boxShadow: "0 2px 10px rgba(0,0,0,0.05)",
                  display: "flex",
                  alignItems: "center",
                  gap: 15,
                }}
              >
                {/* IMAGE */}
                {v.candidateId?.image && (
                  <img
                    src={`${API_URL}/uploads/${v.candidateId.image}`}
                    alt={v.candidateId.firstName}
                    style={{ width: 60, height: 60, borderRadius: 8 }}
                  />
                )}

                {/* INFO */}
                <div>
                  <strong>{v.candidateId?.candidacy}</strong>
                  <p style={{ margin: 0 }}>
                    {v.candidateId?.firstName} {v.candidateId?.lastName}
                  </p>
                </div>
              </div>
            ))}
          </div>

          {/* =========================
              DOWNLOAD BUTTON
          ========================= */}
          <button
            onClick={downloadPDF}
            style={{
              marginTop: 30,
              padding: "12px 25px",
              backgroundColor: "#B11226",
              color: "#fff",
              border: "none",
              borderRadius: 8,
              cursor: "pointer",
              fontSize: 16,
            }}
          >
            Download PDF
          </button>

          {/* =========================
              FEEDBACK SECTION
          ========================= */}
          <div
            style={{
              marginTop: 40,
              padding: 20,
              backgroundColor: "#fff",
              borderRadius: 10,
              boxShadow: "0 2px 10px rgba(0,0,0,0.05)",
              textAlign: "left",
            }}
          >
            <h3>Submit Feedback</h3>

            <textarea
              value={feedback}
              onChange={(e) => setFeedback(e.target.value)}
              placeholder="Write your feedback here..."
              style={{
                width: "100%",
                height: 100,
                padding: 10,
                borderRadius: 8,
                border: "1px solid #ccc",
                marginBottom: 10,
              }}
            />

            <button
              onClick={handleSubmitFeedback}
              disabled={submitting}
              style={{
                padding: "10px 20px",
                backgroundColor: "#B11226",
                color: "#fff",
                border: "none",
                borderRadius: 8,
                cursor: "pointer",
              }}
            >
              {submitting ? "Submitting..." : "Submit Feedback"}
            </button>

            {message && (
              <p style={{ marginTop: 10, color: "green" }}>{message}</p>
            )}
          </div>
        </>
      )}
    </div>
  );
}

export default BallotReceiptPage;
